250 |   /**
251 |    * @dev Computes the interest accrued for a lien since its last payment.
252 |    * @param stack The Lien for the loan to calculate interest for.
253 |    * @param timestamp The timestamp at which to compute interest for.
254 |    */
255 |   function _getInterest(Stack memory stack, uint256 timestamp)
256 |     internal
257 |     pure
258 |     returns (uint256)
259 |   {
260 |     uint256 delta_t = timestamp - stack.point.last;
261 | 
262 |     return (delta_t * stack.lien.details.rate).mulWadDown(stack.point.amount);
263 |   }
