269 |       revert InvalidState(InvalidStates.EMPTY_STATE);
270 |     }
271 |     if (stateHash != bytes32(0) && keccak256(abi.encode(stack)) != stateHash) {
272 |       revert InvalidState(InvalidStates.INVALID_HASH);
